#include <stdio.h>

int main(void)
{
    int a = 1, b = 2;
    int *p = &a;

    p = &b;
    *p = 9;
    printf("%d %d\n", a, b);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int x = 5;
    int *p = &x;
    int **pp = &p;

    **pp = 7;
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int v[] = {10, 20, 30};
    int *p = v + 1;

    printf("%d %d %d\n", *p, p[-1], *(p + 1));
    return 0;
}

#include <stdio.h>

int main(void)
{
    int v[6];
    int *a = &v[1], *b = &v[5];

    printf("%ld\n", (long) (b - a));
    return 0;
}

#include <stdio.h>
